-- Seed: "Core 2K Vocabulary" deck (2001 cards) for test_premium@test.com.
-- Unlike the hiragana deck, these are real kanji words with genuinely
-- ambiguous readings (multiple kanji share readings depending on
-- context) -- romaji/kana/furigana are deliberately left at their
-- column defaults (empty/NULL) rather than guessed here, so the
-- app's existing backfillMissingReadings() picks them up through the
-- real kuromoji-based /api/romaji conversion the next time this
-- account's app is open. With ~2000 cards needing backfill, expect
-- this to take a while (it processes one card at a time, sequentially,
-- while the app stays open/foregrounded) -- it will resume where it
-- left off across multiple app sessions if interrupted.
do $$
declare
  v_uid uuid;
begin
  select id into v_uid from auth.users where email = 'test_premium@test.com';
  if v_uid is null then
    raise exception 'test_premium@test.com not found';
  end if;

  on conflict (id) do nothing;
end $$;
